#!/usr/bin/env node
// Regenerates src/audioProbe/calibrationAssets.generated.ts from the vendored
// calibration assets in src/audioProbe/calibration/ (#663).
//
// The assets ship inside the JavaScript bundle, base64-encoded, so the probe
// needs no served file and no bundler configuration in the host. Each asset
// is checked against its sidecar's hash before it is embedded; a mismatch
// aborts without writing. calibrationAssets.test.ts runs this with --check,
// which fails unless the generated file is exactly what this script writes,
// so a re-vendored asset fails CI until this is rerun, and nothing can be
// added to the generated file by hand.
//
//   node packages/stagebook/scripts/embed-calibration-assets.mjs [--check]

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const COUNTS = [2, 3, 4, 5, 6, 7, 8];
const dir = fileURLToPath(new URL("../src/audioProbe/calibration/", import.meta.url));
const out = fileURLToPath(
  new URL("../src/audioProbe/calibrationAssets.generated.ts", import.meta.url),
);

const entries = COUNTS.map((channels) => {
  const name = `calib_${channels}ch.mp4`;
  const bytes = readFileSync(dir + name);
  const sidecar = JSON.parse(readFileSync(`${dir}${name}.sidecar.json`, "utf8"));
  const sha256 = createHash("sha256").update(bytes).digest("hex");
  if (sidecar.hash !== `sha256:${sha256}`) {
    throw new Error(`${name}: sha256 ${sha256} does not match sidecar ${sidecar.hash}`);
  }
  if (sidecar.direct_transform?.parameters?.channels !== channels) {
    throw new Error(`${name}: sidecar is for a different channel count`);
  }
  return [
    "  {",
    `    channels: ${channels},`,
    `    artifactId: ${JSON.stringify(sidecar.artifact_id)},`,
    `    sha256: ${JSON.stringify(sha256)},`,
    // Laid out as Prettier formats it, so the pre-commit hook leaves the
    // file exactly as written and --check holds.
    "    base64:",
    `      ${JSON.stringify(bytes.toString("base64"))},`,
    "  },",
  ].join("\n");
});

const text = `// Generated by scripts/embed-calibration-assets.mjs from calibration/ — do
// not edit. The channel-order calibration assets, one per channel count, as
// shipped by conversation-processing-pipeline's compose_group (#663).

export const CALIBRATION_ASSETS = [
${entries.join("\n")}
] as const;
`;

if (process.argv.includes("--check")) {
  if (readFileSync(out, "utf8") !== text) {
    console.error(`${out} is not what this script generates; rerun it.`);
    process.exit(1);
  }
} else {
  writeFileSync(out, text);
  console.log(`wrote ${out}`);
}
